    const phoneErr = validatePhone(phoneInput.value);

    renderFieldError(fullNameInput, "fullNameError", nameErr);
    renderFieldError(emailInput, "emailError", emailErr);
    renderFieldError(phoneInput, "phoneError", phoneErr);

    return !nameErr && !emailErr && !phoneErr;
  }

  // --- Live validation on blur (marks field as touched) ---
  function handleBlur(input, errorId, validator) {
    state.touched[input.id] = true;
    const err = validator(input.value);
    renderFieldError(input, errorId, err);
  }

  // --- Live validation on input (only after touched) ---
  function handleInput(input, errorId, validator) {
    if (!state.touched[input.id] && !state.submitted) return;
    const err = validator(input.value);
    renderFieldError(input, errorId, err);
  }

  // --- Event listeners ---
  fullNameInput.addEventListener("blur", () =>
    handleBlur(fullNameInput, "fullNameError", validateFullName)
  );
  fullNameInput.addEventListener("input", () =>
    handleInput(fullNameInput, "fullNameError", validateFullName)
  );

  emailInput.addEventListener("blur", () =>
    handleBlur(emailInput, "emailError", validateEmail)
  );
  emailInput.addEventListener("input", () =>
    handleInput(emailInput, "emailError", validateEmail)
  );

