+(function () {
+  "use strict";
+
+  // --- State ---
+  const state = {
+    touched: { fullName: false, email: false, phone: false },
+    submitted: false,
+  };
+
+  // --- DOM references ---
+  const form = document.getElementById("contactForm");
+  const fullNameInput = document.getElementById("fullName");
+  const emailInput = document.getElementById("email");
+  const phoneInput = document.getElementById("phone");
+  const successBanner = document.getElementById("successBanner");
+
+  const errorEl = (id) => document.getElementById(id);
+
+  // --- Validation rules ---
+  function validateFullName(value) {
+    if (!value.trim()) return "Full name is required.";
+    if (value.trim().length < 2) return "Please enter your full name.";
+    return null;
+  }
+
+  function validateEmail(value) {
+    if (!value.trim()) return "Email address is required.";
+    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    if (!re.test(value.trim())) return "Please enter a valid email address.";
+    return null;
+  }
+
+  function validatePhone(value) {
+    if (!value.trim()) return null; // optional
+    const re = /^\+?[\d\s\-().]{7,20}$/;
+    if (!re.test(value.trim())) return "Please enter a valid phone number.";
+    return null;
+  }
+
+  // --- Render error for a single field ---
+  function renderFieldError(input, errorId, errorMessage) {
+    const errEl = errorEl(errorId);
+    if (errorMessage) {
+      input.classList.add("invalid");
+      errEl.textContent = errorMessage;
+      errEl.classList.add("visible");
+      input.setAttribute("aria-invalid", "true");
+    } else {
+      input.classList.remove("invalid");
+      errEl.textContent = "";
+      errEl.classList.remove("visible");
+      input.setAttribute("aria-invalid", "false");
+    }
+  }
+
+  // --- Validate and render all fields, return true if form is valid ---
+  function validateAll() {
+    const nameErr = validateFullName(fullNameInput.value);
+    const emailErr = validateEmail(emailInput.value);
+    const phoneErr = validatePhone(phoneInput.value);
+
+    renderFieldError(fullNameInput, "fullNameError", nameErr);
